package com.travbook;
import com.travbook.journeys.application.port.in.*;
import com.travbook.journeys.application.port.out.*;
import com.travbook.journeys.domain.model.Care;
import com.travbook.journeys.domain.model.Journey.*;
import com.travbook.shared.domain.*;
import com.travbook.buses.domain.model.Bus;
import com.travbook.holidays.domain.model.Holiday;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"JOURNEY_WORKER_ENABLED=false","JOURNEY_CARE_WORKER_ENABLED=false","travbook.payments.refund-worker-enabled=false"})
class AdvancedJourneyIntegrationTest extends JourneyIntegrationTest {
 @Autowired AdvancedJourneys advanced;@Autowired JourneyCareStore careStore;@Autowired ProcessJourneyCare careWorker;@Autowired JourneyCareEffects careEffects;@Autowired com.travbook.operations.application.port.in.Operations operations;
 Request busParty(int offset){var page=buses.search(new Bus.Criteria(Bus.City.DELHI,Bus.City.JAIPUR,LocalDate.now(clock).plusDays(offset),List.of(30,10)));var trip=page.items().getFirst();return new Request(Kind.BUS,page.id(),trip.id(),List.of("L1","L2"),trip.boarding().getFirst().id(),trip.dropping().getFirst().id());}
 Request packageFuture(){var p=holidays.detail("sample-goa-coast");var q=holidays.quote(identity,new Holiday.Selection(p.id(),p.departures().get(2),1,List.of(),Holiday.Upgrade.STANDARD,false),key(),correlation());holidays.enquire(identity,q.id(),new Holiday.Contact("Sample","sample@example.test",""),true,key(),correlation());return new Request(Kind.HOLIDAY,q.id(),null,List.of(),null,null);}
 Care.Summary advancedBook(Request r,Care.Plan plan){var q=advanced.quote(identity,r,plan,key(),correlation());advanced.accept(identity,q.details().quote().id(),2,true,key(),correlation());var ages=q.details().quote().selection().passengerAges();var people=new ArrayList<Passenger>();for(int i=0;i<ages.size();i++)people.add(new Passenger(i==0?"Adult Sample":"Young Sample",ages.get(i)<0?30:ages.get(i)));return advanced.book(identity,q.details().quote().id(),people,"sample@example.test",Scenario.NORMAL,key(),correlation());}
 Care.Summary confirmed(Care.Summary s){UUID id=s.booking().id();for(int n=0;n<30&&advanced.get(identity,id).booking().status()==Status.HOLD_PENDING;n++){worker.tick();clock.now=clock.now.plusMillis(100);}advanced.pay(identity,id,key(),correlation());for(int n=0;n<60;n++){worker.tick();clock.now=clock.now.plusMillis(100);s=advanced.get(identity,id);if(s.booking().status()==Status.CONFIRMED)return s;}throw new AssertionError("Not confirmed: "+s.booking().step());}
 Care.Summary finishCare(UUID id){for(int n=0;n<80;n++){careWorker.tick();worker.tick();refunds.settleNext();clock.now=clock.now.plusSeconds(2);var s=advanced.get(identity,id);if(s.actions().stream().noneMatch(a->!a.terminal()))return s;}throw new AssertionError("Care did not finish");}
 Care.Action cancel(Care.Summary s,List<String> ids,boolean loss){var q=advanced.cancellationQuote(identity,s.booking().id(),ids,key(),correlation());return advanced.cancel(identity,s.booking().id(),q.id(),true,false,loss,key(),correlation());}
 @Test void legacyPendingRefundRemainsVisibleThroughTheNewProjection(){var b=finish(book(cab(),Scenario.NORMAL));var q=journeys.cancellationQuote(identity,b.id(),key(),correlation());journeys.cancel(identity,b.id(),q.id(),true,true,key(),correlation());worker.tick();assertThat(advanced.get(identity,b.id()).funding().refundPending()).isEqualTo(b.quote().selection().total());worker.tick();assertThat(advanced.get(identity,b.id()).funding().status()).isEqualTo("REFUND_PENDING");clock.now=clock.now.plusSeconds(10);refunds.settleNext();worker.tick();assertThat(advanced.get(identity,b.id()).funding().refunded()).isEqualTo(b.quote().selection().total());assertThat(advanced.get(identity,b.id()).funding().refundPending().decimal()).isZero();}
 @Test void unpaidFundingShowsTheEntireAmountBeforeInitialCapture(){for(var plan:Care.Plan.values()){var b=advancedBook(packageFuture(),plan);assertThat(b.funding().status()).isEqualTo("UNPAID");assertThat(b.funding().paid().decimal()).isZero();assertThat(b.funding().outstanding()).isEqualTo(b.booking().quote().selection().total());}}
 @Test void partialSeatsRefundOnlyChosenFareAndKeepEligibleRemainingTicket(){day=70;var s=confirmed(advancedBook(busParty(day),Care.Plan.FULL));UUID id=s.booking().id();assertThatThrownBy(()->advanced.cancellationQuote(identity,id,List.of("L1"),key(),correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("adult");var q=advanced.cancellationQuote(identity,id,List.of("L2"),key(),correlation());assertThat(q.refundAmount().decimal()).isEqualByComparingTo("700");String k=key();var a=advanced.cancel(identity,id,q.id(),true,false,true,k,correlation());assertThat(advanced.cancel(identity,id,q.id(),true,false,true,k,correlation()).id()).isEqualTo(a.id());s=finishCare(id);assertThat(s.booking().status()).isEqualTo(Status.CONFIRMED);assertThat(s.activeComponentIds()).containsExactly("L1");assertThat(s.funding().refunded().decimal()).isEqualByComparingTo("700");assertThat(advanced.document(identity,id).content()).contains("Seat L1","Adult Sample").doesNotContain("Seat L2","Young Sample");assertThatThrownBy(()->advanced.cancellationQuote(identity,id,List.of("L2"),key(),correlation())).isInstanceOf(DomainFailure.class);cancel(s,List.of("L1"),false);s=finishCare(id);assertThat(s.booking().status()).isEqualTo(Status.CANCELLED);assertThat(s.funding().refunded()).isEqualTo(s.funding().paid());assertThat(jdbc.sql("select count(*) from journey_supplier_seat where booking_id=:id").param("id",id).query(Integer.class).single()).isZero();}
 @Test void depositIsDistinctFromFullPaymentAndFinalVoucher(){var s=confirmed(advancedBook(packageFuture(),Care.Plan.DEPOSIT));UUID id=s.booking().id();assertThat(s.funding().status()).isEqualTo("DEPOSIT_PAID");assertThat(s.funding().paid()).isEqualTo(s.terms().firstAmount());assertThat(s.documentAvailable()).isFalse();assertThatThrownBy(()->advanced.document(identity,id)).isInstanceOf(DomainFailure.class);assertThatThrownBy(()->advanced.cancellationQuote(identity,id,List.of("activities"),key(),correlation())).isInstanceOf(DomainFailure.class);advanced.balance(identity,id,false,true,key(),correlation());s=finishCare(id);assertThat(s.funding().status()).isEqualTo("PAID");assertThat(s.funding().paid()).isEqualTo(s.booking().quote().selection().total());assertThat(advanced.document(identity,id).content()).contains("fully paid");assertThatThrownBy(()->advanced.balance(identity,id,false,false,key(),correlation())).isInstanceOf(DomainFailure.class);cancel(s,List.of("activities"),true);s=finishCare(id);assertThat(s.activeComponentIds()).containsExactly("accommodation","transfers");assertThat(s.funding().refunded().decimal()).isEqualByComparingTo(s.booking().quote().selection().components().get(2).amount().decimal());assertThat(advanced.document(identity,id).content()).contains("Activity itinerary removed");cancel(s,s.activeComponentIds(),false);s=finishCare(id);assertThat(s.funding().refunded()).isEqualTo(s.funding().paid());}
 @Test void fullCancellationBeforeBalanceReturnsOnlyCollectedDeposit(){var s=confirmed(advancedBook(packageFuture(),Care.Plan.DEPOSIT));var q=advanced.cancellationQuote(identity,s.booking().id(),s.activeComponentIds(),key(),correlation());assertThat(q.refundAmount()).isEqualTo(s.terms().firstAmount());assertThat(q.unpaidAmountCancelled()).isEqualTo(s.terms().balanceAmount());advanced.cancel(identity,s.booking().id(),q.id(),true,false,false,key(),correlation());s=finishCare(s.booking().id());assertThat(s.funding().refunded()).isEqualTo(s.terms().firstAmount());assertThat(s.funding().outstanding().decimal()).isZero();}
 @Test void missedBalanceDeadlineCancelsAndRefundsWithoutCollectingRemainder(){var s=confirmed(advancedBook(packageFuture(),Care.Plan.DEPOSIT));clock.now=s.terms().balanceDue().plusSeconds(1);assertThat(careWorker.tick()).isTrue();s=finishCare(s.booking().id());assertThat(s.booking().status()).isEqualTo(Status.CANCELLED);assertThat(s.funding().paid()).isEqualTo(s.terms().firstAmount());assertThat(s.funding().refunded()).isEqualTo(s.funding().paid());assertThat(s.actions()).noneMatch(a->a.type()==Care.Type.BALANCE);}
 @Test void declinedBalanceCanBeRetriedWithFreshIntentWithoutDuplicateCapture(){var s=confirmed(advancedBook(packageFuture(),Care.Plan.DEPOSIT));UUID id=s.booking().id();advanced.balance(identity,id,true,false,key(),correlation());s=finishCare(id);assertThat(s.funding().status()).isEqualTo("DEPOSIT_PAID");advanced.balance(identity,id,false,false,key(),correlation());s=finishCare(id);assertThat(s.funding().status()).isEqualTo("PAID");assertThat(jdbc.sql("select count(*) from payment_account where id in(select id from journey_care_action where booking_id=:id and type='BALANCE') and status='CAPTURED'").param("id",id).query(Integer.class).single()).isEqualTo(1);}
 @Test void rescheduleConfirmsReplacementBeforeOriginalCancellationAndRefund(){day=72;var original=confirmed(advancedBook(busParty(day),Care.Plan.FULL));UUID id=original.booking().id();var request=busParty(day+1);var sleeper=buses.page(request.sourceId(),Bus.Filter.defaults()).items().stream().filter(t->t.type()==Bus.Type.SLEEPER&&t.supplier().equals(original.booking().quote().selection().supplier())).findFirst().orElseThrow();request=new Request(Kind.BUS,request.sourceId(),sleeper.id(),List.of("L1","L2"),sleeper.boarding().getFirst().id(),sleeper.dropping().getFirst().id());var q=advanced.rescheduleQuote(identity,id,request,key(),correlation());assertThat(q.details().quote().selection().total().decimal()).isGreaterThan(original.booking().quote().selection().total().decimal());advanced.accept(identity,q.details().quote().id(),2,true,key(),correlation());assertThat(q.replacement().version()).isEqualTo(original.booking().version());var a=advanced.reschedule(identity,id,q.details().quote().id(),original.booking().version(),true,key(),correlation());assertThat(advanced.get(identity,id).booking().status()).isEqualTo(Status.CONFIRMED);confirmed(advanced.get(identity,a.replacementId()));var done=finishCare(id);assertThat(done.booking().status()).isEqualTo(Status.CANCELLED);assertThat(done.funding().refunded()).isEqualTo(done.funding().paid());var replacement=advanced.get(identity,a.replacementId());assertThat(replacement.booking().status()).isEqualTo(Status.CONFIRMED);assertThat(replacement.rescheduledFrom()).isEqualTo(id);assertThat(replacement.funding().paid()).isEqualTo(q.details().quote().selection().total());assertThatThrownBy(()->advanced.document(identity,id)).isInstanceOf(DomainFailure.class);assertThat(advanced.document(identity,a.replacementId()).content()).contains(replacement.booking().quote().selection().departureAt().toString());}
 @Test void unpaidReplacementExpiryLeavesOriginalConfirmed(){day=75;var b=confirmed(advancedBook(busParty(day),Care.Plan.FULL));var q=advanced.rescheduleQuote(identity,b.booking().id(),busParty(day+1),key(),correlation());advanced.accept(identity,q.details().quote().id(),2,true,key(),correlation());var a=advanced.reschedule(identity,b.booking().id(),q.details().quote().id(),b.booking().version(),true,key(),correlation());worker.tick();clock.now=q.details().quote().expiresAt().plusSeconds(1);var done=finishCare(b.booking().id());assertThat(done.booking().status()).isEqualTo(Status.CONFIRMED);assertThat(done.funding().refunded().decimal()).isZero();assertThat(done.actions()).anyMatch(v->v.type()==Care.Type.RESCHEDULE&&v.status()==Care.State.FAILED);assertThat(advanced.get(identity,a.replacementId()).booking().status()).isEqualTo(Status.FAILED);}
 @Test void cabDemoIsOwnedIdempotentForwardOnlyAndInvalidatedByCancellation()throws Exception{var s=confirmed(advancedBook(cab(),Care.Plan.FULL));UUID id=s.booking().id();var d=advanced.dispatch(identity,id);assertThat(d.stage()).isEqualTo(Care.Stage.ASSIGNED);String k=key();var next=advanced.advanceDemo(identity,id,d.version(),true,k,correlation());assertThat(advanced.advanceDemo(identity,id,d.version(),true,k,correlation())).isEqualTo(next);long oldVersion=d.version();assertThatThrownBy(()->advanced.advanceDemo(identity,id,oldVersion,true,key(),correlation())).isInstanceOf(DomainFailure.class);for(int n=0;n<3;n++){d=advanced.dispatch(identity,id);advanced.advanceDemo(identity,id,d.version(),true,key(),correlation());}assertThat(advanced.dispatch(identity,id).stage()).isEqualTo(Care.Stage.COMPLETED);assertThat(call("/api/v2/journey-bookings/"+id+"/dispatch",issuer.token("other-dispatch","bookings:read")).statusCode()).isEqualTo(404);cancel(s,s.activeComponentIds(),false);finishCare(id);assertThat(advanced.dispatch(identity,id).stage()).isEqualTo(Care.Stage.CANCELLED);assertThatThrownBy(()->advanced.advanceDemo(identity,id,5,true,key(),correlation())).isInstanceOf(DomainFailure.class);}
 @Test void enhancedResourcesCannotUseLegacyMutationOrDocumentEndpoints()throws Exception{var s=confirmed(advancedBook(cab(),Care.Plan.FULL));assertThat(call("/api/v1/journey-bookings/"+s.booking().id(),token).statusCode()).isEqualTo(409);var response=call("/api/v2/journey-bookings/"+s.booking().id(),token);assertThat(response.statusCode()).as(response.body()).isEqualTo(200);var value=json.readTree(response.body());assertThat(value.get("id").asString()).isEqualTo(s.booking().id().toString());assertThat(value.has("core")).isFalse();assertThat(value.has("funding")).isTrue();}
 @Test void careReviewRecoveryKeepsAuditAndDoesNotRepeatProviderEffects(){day=82;var b=confirmed(advancedBook(busParty(day),Care.Plan.FULL));cancel(b,List.of("L2"),false);var claim=careStore.claim().orElseThrow();careEffects.execute(claim.action());assertThat(careStore.complete(claim,claim.action().review(clock.instant()))).isTrue();var reviewed=advanced.get(identity,b.booking().id());var c=operations.get(Recovery.Kind.BUS,b.booking().id());assertThat(c.recoverable()).isTrue();var audit=operations.resume(Recovery.Kind.BUS,b.booking().id(),reviewed.booking().version(),"a".repeat(64),Recovery.Reason.PROVIDER_STATUS_AVAILABLE,true,key(),correlation());assertThat(jdbc.sql("select count(*) from journey_care_outbox where envelope->>'causationId'=:id").param("id",audit.id().toString()).query(Integer.class).single()).isEqualTo(1);var done=finishCare(b.booking().id());assertThat(done.activeComponentIds()).containsExactly("L1");assertThat(operations.get(Recovery.Kind.BUS,b.booking().id()).actions()).hasSize(1);assertThat(jdbc.sql("select count(*) from journey_supplier_care_receipt where booking_id=:id").param("id",b.booking().id()).query(Integer.class).single()).isEqualTo(1);}
 @Test void careOutboxFailureRollsBackRequestAndIdempotency(){day=84;var b=confirmed(advancedBook(busParty(day),Care.Plan.FULL));var q=advanced.cancellationQuote(identity,b.booking().id(),List.of("L2"),key(),correlation());String k=key();jdbc.sql("create function reject_care_event() returns trigger language plpgsql as $$ begin raise exception 'Injected'; end $$").update();jdbc.sql("create trigger reject_care_event before insert on journey_care_outbox for each row execute function reject_care_event()").update();try{assertThatThrownBy(()->advanced.cancel(identity,b.booking().id(),q.id(),true,false,false,k,correlation())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(advanced.get(identity,b.booking().id()).actions()).isEmpty();assertThat(advanced.get(identity,b.booking().id()).booking().version()).isEqualTo(b.booking().version());}finally{jdbc.sql("drop trigger reject_care_event on journey_care_outbox").update();jdbc.sql("drop function reject_care_event()").update();}advanced.cancel(identity,b.booking().id(),q.id(),true,false,false,k,correlation());assertThat(finishCare(b.booking().id()).funding().refunded().decimal()).isEqualByComparingTo("700");}
 @Test void actualCareProcessCrashRecoversImmutableEntitlement()throws Exception{day=86;var b=confirmed(advancedBook(busParty(day),Care.Plan.FULL));var a=cancel(b,List.of("L2"),false);assertThat(jdbc.sql("select count(*) from journey_care_quote_use where action_id=:id").param("id",a.id()).query(Integer.class).single()).isEqualTo(1);assertThatThrownBy(()->jdbc.sql("update journey_care_action set payload=jsonb_set(payload,'{refunds,0,amount,amount}','\"0.01\"') where id=:id").param("id",a.id()).update()).isInstanceOf(org.springframework.dao.DataAccessException.class);var claim=careStore.claim().orElseThrow();var log=java.nio.file.Files.createTempFile("journey-care-crash-",".log");try{var cp=System.getProperty("surefire.test.class.path",System.getProperty("java.class.path"));var pb=new ProcessBuilder(java.nio.file.Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",cp,"com.travbook.support.JourneyCareProcess",b.booking().quote().owner().toString(),b.booking().id().toString(),a.id().toString()).redirectErrorStream(true).redirectOutput(log.toFile());pb.environment().put("DATABASE_URL",postgres.getJdbcUrl());pb.environment().put("DATABASE_USERNAME",postgres.getUsername());pb.environment().put("DATABASE_PASSWORD",postgres.getPassword());var process=pb.start();boolean done=process.waitFor(30,TimeUnit.SECONDS);if(!done)process.destroyForcibly();assertThat(done).isTrue();assertThat(process.exitValue()).withFailMessage(java.nio.file.Files.readString(log)).isEqualTo(31);}finally{java.nio.file.Files.deleteIfExists(log);}jdbc.sql("update journey_care_work set lease_until=clock_timestamp()-interval '1 second' where action_id=:id").param("id",claim.action().id()).update();assertThat(finishCare(b.booking().id()).funding().refunded().decimal()).isEqualByComparingTo("700");assertThat(jdbc.sql("select count(*) from journey_supplier_care_receipt where booking_id=:id").param("id",b.booking().id()).query(Integer.class).single()).isEqualTo(1);}
 @Test void careCrashLeaseAndConcurrentRequestsDoNotDuplicateRefund()throws Exception{day=78;var s=confirmed(advancedBook(busParty(day),Care.Plan.FULL));var q=advanced.cancellationQuote(identity,s.booking().id(),List.of("L2"),key(),correlation());UUID id=s.booking().id();String k=key();try(var pool=Executors.newFixedThreadPool(2)){var results=pool.invokeAll(List.<Callable<Care.Action>>of(()->advanced.cancel(identity,id,q.id(),true,false,false,k,correlation()),()->advanced.cancel(identity,id,q.id(),true,false,false,k,correlation())));assertThat(results.get(0).get().id()).isEqualTo(results.get(1).get().id());}var claim=careStore.claim().orElseThrow();var receipt=careEffects.execute(claim.action());jdbc.sql("update journey_care_work set lease_until=clock_timestamp()-interval '1 second' where action_id=:id").param("id",claim.action().id()).update();assertThat(careStore.complete(claim,claim.action().result(receipt.accepted(),receipt.completed(),receipt.reference(),clock.instant()))).isFalse();s=finishCare(id);assertThat(s.funding().refunded().decimal()).isEqualByComparingTo("700");assertThat(jdbc.sql("select count(*) from journey_supplier_care_receipt where booking_id=:id").param("id",id).query(Integer.class).single()).isEqualTo(1);}
}
